    from app.routes.users import bp as users_bp
    from app.routes.orders import bp as orders_bp
    app.register_blueprint(users_bp, url_prefix="/api/v1/users")
    app.register_blueprint(orders_bp, url_prefix="/api/v1/orders")
    return app
from functools import wraps
from flask import request
from app import fail


def login_required(fn):
    @wraps(fn)
    def wrapper(*a, **kw):
        if not request.headers.get("X-User-Id"):
            return fail(40100, "unauthorized", 401)
        return fn(*a, **kw)
    return wrapper
from flask import Blueprint, request
from app import ok, fail
from app.auth import login_required

bp = Blueprint("orders", __name__)

STATUSES = ("CREATED", "PAID", "SHIPPED", "CANCELLED")


@bp.post("")
@login_required
def create_order():
    body = request.get_json(silent=True) or {}
    items = body.get("items")
    if not items:
        return fail(40001, "items required")
    for it in items:
        if not it.get("skuId") or not 0 < int(it.get("qty", 0)) <= 99:
            return fail(40002, "invalid item")
    order = {
        "orderId": "O" + "1" * 12,
        "status": "CREATED",
        "items": [{"skuId": it["skuId"], "qty": int(it["qty"])} for it in items],
        "note": body.get("note", ""),
        "couponCode": body.get("couponCode"),
        "payAmount": "0.00",
    }
    return ok(order)


@bp.get("/<order_id>")
@login_required
def get_order(order_id):
    if not order_id.startswith("O"):
        return fail(40400, "order not found", 404)
    return ok({"orderId": order_id, "status": "CREATED", "items": [], "note": ""})


@bp.get("")
@login_required
def list_orders():
    page = int(request.args.get("page", 1))
    size = min(int(request.args.get("size", 20)), 100)
    status = request.args.get("status")
    if status and status not in STATUSES:
        return fail(40003, "invalid status")
    return ok({"page": page, "size": size, "total": 0, "list": []})


