import json
import re
import subprocess
import sys
import types
from pathlib import Path
from unittest.mock import patch


def load(ref):
    request = types.SimpleNamespace()

    class Blueprint:
        def __init__(self, *args):
            self.routes = {}

        def route(self, method, path):
            def register(handler):
                self.routes[method, path] = handler
                return handler
            return register

        def get(self, path):
            return self.route(\"GET\", path)

        def post(self, path):
            return self.route(\"POST\", path)

    class Flask:
        def __init__(self, *args):
            self.routes = {}

        def register_blueprint(self, blueprint, url_prefix):
            self.routes.update({
                (method, url_prefix + path): handler
                for (method, path), handler in blueprint.routes.items()
            })

    imports = {\"flask\": types.SimpleNamespace(
        Blueprint=Blueprint, Flask=Flask, jsonify=lambda payload: payload, request=request
    )}
    with patch.dict(sys.modules, imports):
        for name, filename in (
            (\"app\", \"app/__init__.py\"),
            (\"app.auth\", \"app/auth.py\"),
            (\"app.routes.orders\", \"app/routes/orders.py\"),
            (\"app.routes.users\", \"app/routes/users.py\"),
        ):
            module = types.ModuleType(name)
            sys.modules[name] = module
            source = subprocess.check_output([\"git\", \"show\", ref + \":\" + filename])
            exec(compile(source, ref + \":\" + filename, \"exec\"), module.__dict__)
        app = sys.modules[\"app\"].create_app()

    def call(method, path, body=None, order_id=None, logged_in=True):
        request.headers = {\"X-User-Id\": \"U123\"} if logged_in else {}
        request.get_json = lambda silent=False: body
        request.args = {}
        args = () if order_id is None else (order_id,)
        result = app.routes[method, path](*args)
        return result if isinstance(result, tuple) else (result, 200)

    return set(app.routes), call


